// Regional 3DEP patch in the game's rounded UTM 19N coordinates. Generated by tools/geology/bake_kineo.py.
(() => {
  'use strict';
  const records=/*AREA_DATA*/[];
  const origins=/*ORIGINS*/[];
  const areas=records.map(a=>({...a,grid:new Int16Array(Uint8Array.from(atob(a.heights),c=>c.charCodeAt(0)).buffer)}));
  const smooth=t=>{t=Math.min(1,Math.max(0,t));return t*t*(3-2*t);};
  function weight(a,x,z){const [l,t,r,b]=a.rect;return smooth(Math.min(x-l,r-x,z-t,b-z)/13);}
  function elevation(x,z,base){
    for(const a of areas){
      const [l,t,r,b]=a.rect;if(x<=l||x>=r||z<=t||z>=b)continue;
      const ix=Math.floor(x-l),iz=Math.floor(z-t),dx=x-l-ix,dz=z-t-iz,n=r-l+1,k=iz*n+ix,h=a.grid;
      const value=300+((1-dz)*((1-dx)*h[k]+dx*h[k+1])+dz*((1-dx)*h[k+n]+dx*h[k+n+1]))/128;
      return base+(value-base)*weight(a,x,z);
    }
    return base;
  }
  window.kineoSurvey={areas,elevation};
  async function readGLB(T,file){
    const res=await fetch(file);if(!res.ok)throw new Error('Missing Kineo model '+file);
    const bytes=await res.arrayBuffer(),view=new DataView(bytes);
    if(view.getUint32(0)!==0x676c5446)throw new Error('Invalid Kineo GLB');
    const length=view.getUint32(12,true),doc=JSON.parse(new TextDecoder().decode(new Uint8Array(bytes,20,length))),start=28+length;
    const part=doc.meshes[0].primitives[0],geometry=new T.BufferGeometry();
    for(const [field,id] of Object.entries({...part.attributes,index:part.indices})){
      const a=doc.accessors[id],v=doc.bufferViews[a.bufferView],off=start+(v.byteOffset||0)+(a.byteOffset||0);
      const size={VEC2:2,VEC3:3,SCALAR:1}[a.type],Arr=a.componentType===5123?Uint16Array:Float32Array;
      const attr=new T.BufferAttribute(new Arr(bytes,off,a.count*size),size);
      if(field==='index')geometry.setIndex(attr);
      else geometry.setAttribute({POSITION:'position',NORMAL:'normal',TEXCOORD_0:'uv',TEXCOORD_1:'uv1',COLOR_0:'color'}[field],attr);
    }
    const textures=await Promise.all(doc.images.map(async image=>{
      const v=doc.bufferViews[image.bufferView],data=new Blob([new Uint8Array(bytes,start+v.byteOffset,v.byteLength)],{type:image.mimeType});
      const url=URL.createObjectURL(data);
      try{return await new T.TextureLoader().loadAsync(url);}finally{URL.revokeObjectURL(url);}
    }));
    for(const tx of textures){tx.flipY=false;tx.wrapS=tx.wrapT=T.RepeatWrapping;tx.anisotropy=4;}
    const [map,normal,orm]=textures;map.colorSpace=T.SRGBColorSpace;normal.channel=orm.channel=1;
    const spec=doc.materials[part.material],s=spec.normalTexture.scale;
    const mat=new T.MeshStandardMaterial({map,normalMap:normal,aoMap:orm,roughnessMap:orm,roughness:1,metalness:0,aoMapIntensity:spec.occlusionTexture.strength,normalScale:new T.Vector2(s,s),vertexColors:!!geometry.attributes.color,side:T.DoubleSide});
    geometry.computeBoundingSphere();return new T.Mesh(geometry,mat);
  }
  function matchSurveyLight(T,mesh,world,offset){
    // The regional terrain uses a measured horizon field in its own linear
    // lighting pipeline. Apply that same shader directly to these adjoining
    // GLB positions so the edge colours meet in full daylight and shadow.
    const scan=mesh.material,native=world.kineoTerrainMaterial;
    const material=native.clone();
    scan.map.colorSpace=T.NoColorSpace;
    const origin=new T.Vector3().fromArray(offset);
    material.uniforms={...native.uniforms,surveyBase:{value:scan.map},surveyNormal:{value:scan.normalMap},surveyOrigin:{value:origin}};
    mesh.geometry.setAttribute('surveyDetailUv',mesh.geometry.getAttribute('uv1'));
    material.vertexShader='uniform vec3 surveyOrigin;attribute vec2 surveyDetailUv;varying vec2 captureUv,detailUv;\n'+native.vertexShader.replace('wp=position;','wp=position+surveyOrigin;captureUv=uv;detailUv=surveyDetailUv;');
    const isEastWall=mesh.name==='kineo-east-cliff';
    material.fragmentShader=isEastWall?native.fragmentShader:'uniform sampler2D surveyBase,surveyNormal;varying vec2 captureUv,detailUv;\n'+native.fragmentShader.replace('float green=smoothstep',`
      vec2 edge=min(captureUv,1.-captureUv);
      float site=smoothstep(0.,.12,edge.x)*smoothstep(0.,.10,edge.y);
      vec3 field=texture2D(surveyBase,captureUv).rgb;
      vec3 grain=texture2D(surveyNormal,detailUv).rgb*2.-1.;
      float nearSurface=1.-smoothstep(55.,500.,d);
      float mortar=.70+.26*nearSurface;
      // Retain the broader host rock palette with distance; preserve the
      // measured joints and local source texture at close flying distances.
      float mineralValue=clamp((lum(field)+.09)/.565,.50,1.58);
      vec3 measured=mix(c*(.68+.32*mineralValue),field*(.86+.21*nearSurface),.42+.48*nearSurface);
      c=mix(c,measured,site*mortar);
      incidence=mix(incidence,max(0.,dot(normalize(relieved+vec3(grain.x*.21,grain.y*.21,0.)),sun)),site*nearSurface*.80);
      float green=smoothstep`);
    material.side=T.DoubleSide;mesh.material=material;mesh.userData.originalSurveyMaterial=scan;
  }
  // The former fire lookout now has an open observation platform. Survey
  // waypoint 45.69978 N, 69.73373 W in the game's rounded UTM 19N frame.
  function addSummitLookout(T,group,world){
    const x=107.14,z=-863.64,platformHeight=18.42,railHeight=1.08;
    const originY=world.elevation(x,z),baseHalf=3.20,deckHalf=1.86;
    const geometry=new T.BoxGeometry(1,1,1),verts=geometry.attributes.position,index=geometry.index;
    const position=[],color=[],transform=new T.Matrix4(),q=new T.Quaternion();
    const start=new T.Vector3(),end=new T.Vector3(),axis=new T.Vector3(),vertex=new T.Vector3(),mid=new T.Vector3();
    const up=new T.Vector3(0,1,0),scale=new T.Vector3(),pigment=new T.Color();
    const metal=0x88877f,shadow=0x636660,rust=0x8c7867,board=0x9e9382;
    function bar(a,b,width,depth,tone){
      start.fromArray(a);end.fromArray(b);axis.subVectors(end,start);
      const length=axis.length();if(length<.001)return;
      q.setFromUnitVectors(up,axis.multiplyScalar(1/length));
      transform.compose(mid.copy(start).lerp(end,.5),q,scale.set(width,length,depth));
      pigment.setHex(tone);
      for(let i=0;i<index.count;i++){
        vertex.fromBufferAttribute(verts,index.getX(i)).applyMatrix4(transform);
        position.push(vertex.x,vertex.y,vertex.z);color.push(pigment.r,pigment.g,pigment.b);
      }
    }
    function slab(cx,cy,cz,sx,sy,sz,tone){bar([cx,cy-sy/2,cz],[cx,cy+sy/2,cz],sx,sz,tone);}
    function half(y){return baseHalf+(deckHalf-baseHalf)*y/platformHeight;}
    const corners=[[-1,-1],[1,-1],[1,1],[-1,1]];
    const corner=(i,y)=>[corners[i][0]*half(y),y,corners[i][1]*half(y)];
    const heights=[.40,4.92,9.42,13.92,platformHeight];
    for(let i=0;i<4;i++){
      const [u,v]=corners[i],baseY=world.elevation(x+baseHalf*u,z+baseHalf*v)-originY;
      slab(baseHalf*u,baseY-.03,baseHalf*v,.72,.40,.72,0xa1a09a);
      bar([baseHalf*u,baseY+.10,baseHalf*v],corner(i,platformHeight),.154,.154,metal);
      const next=(i+1)%4;
      for(let j=1;j<heights.length;j++){
        const low=heights[j-1],high=heights[j];
        bar(corner(i,high),corner(next,high),.136,.108,j%2?metal:shadow);
        bar(corner(i,low+.09),corner(next,high-.12),.050,.049,shadow);
        bar(corner(next,low+.09),corner(i,high-.12),.049,.046,j%2?rust:shadow);
      }
    }
    // Reversing flights and grated landings are visible through the truss.
    const stairWidth=.88;
    for(let n=0;n<4;n++){
      const from=n%2?-1:1,lane=n%2?.53:-.53;
      const low=heights[n],high=heights[n+1],run=Math.min(half(high)-.36,1.74);
      const count=17;
      for(const side of [-1,1]){
        const t=lane+side*stairWidth/2;
        bar([t,low,from*run],[t,high,-from*run],.078,.095,shadow);
        bar([t,low+.88,from*run],[t,high+.88,-from*run],.038,.038,metal);
      }
      for(let j=0;j<count;j++){
        const f=(j+.5)/count,cz=from*run*(1-2*f),cy=low+(high-low)*f;
        slab(lane,cy,cz,stairWidth,.045,.19,j%4?metal:rust);
        if(j%6===2)for(const side of [-1,1])bar([lane+side*stairWidth/2,cy,cz],[lane+side*stairWidth/2,cy+.88,cz],.038,.038,shadow);
      }
      for(let j=0;j<9;j++)slab(0,high,-from*(run-.08+j*.062),2.0,.075,.036,metal);
    }
    const deckWidth=2*(deckHalf+.07),strip=deckWidth/23;
    for(let j=0;j<23;j++){
      const u=(j-11)*strip,open=u>.09&&u<1.03;
      const last=open?.65:deckWidth/2,first=-deckWidth/2;
      slab(u,platformHeight+.055,(first+last)/2,strip-.013,.117,last-first,j%6?board:0x887f70);
    }
    const top=platformHeight+railHeight;
    for(let i=0;i<4;i++){
      const [u,v]=corners[i],[nx,nz]=corners[(i+1)%4];
      for(const f of [0,.5]){
        const ax=(u+(nx-u)*f)*deckHalf,az=(v+(nz-v)*f)*deckHalf;
        bar([ax,platformHeight,az],[ax,top,az],.062,.062,metal);
      }
      for(const h of [.26,.58,railHeight])bar([u*deckHalf,platformHeight+h,v*deckHalf],[nx*deckHalf,platformHeight+h,nz*deckHalf],h===railHeight?.066:.038,.055,metal);
    }
    geometry.dispose();
    const shape=new T.BufferGeometry();
    shape.setAttribute('position',new T.Float32BufferAttribute(position,3));
    shape.setAttribute('color',new T.Float32BufferAttribute(color,3));
    shape.computeVertexNormals();shape.computeBoundingSphere();
    const surface=new T.MeshStandardMaterial({vertexColors:true,metalness:.23,roughness:.73});
    const mesh=new T.Mesh(shape,surface);mesh.name='Kineo observation platform and stair tower';
    mesh.position.set(x,originY,z);group.add(mesh);
    const prior=world.clearance;
    function withTower(px,pz,altitude){
      const ground=prior(px,pz,altitude);
      if(Math.max(Math.abs(px-x),Math.abs(pz-z))>baseHalf+.1)return ground;
      const above=altitude-originY,ax=Math.abs(px-x),az=Math.abs(pz-z);
      if((!Number.isFinite(above)||above>=platformHeight-.45)&&Math.max(ax,az)<deckHalf+.11)
        return Math.max(ground,originY+platformHeight+.12+(Math.max(ax,az)>deckHalf-.12?railHeight:0));
      if(above>=0&&above<platformHeight&&Math.abs(ax-half(above))<.17&&Math.abs(az-half(above))<.17)
        return Math.max(ground,altitude+.12);
      return ground;
    }
    world.clearance=withTower;
    return ()=>{if(world.clearance===withTower)world.clearance=prior;mesh.removeFromParent();shape.dispose();surface.dispose();};
  }
  window.loadKineoModels=async(T,group,world,file)=>{
    const fetched=await fetch(file('kineo-seams.bin'));if(!fetched.ok)throw new Error('Kineo survey seam unavailable');
    const buffer=await fetched.arrayBuffer(),head=new DataView(buffer),shells=[];
    let at=4;
    for(const area of areas){
      const n=head.getUint32(at,true),ni=head.getUint32(at+4,true);at+=8;
      const pos=new Float32Array(buffer,at,n*3);at+=n*12;
      const ix=new Uint16Array(buffer,at,ni);at=(at+ni*2+3)&~3;
      for(let i=0;i<n;i++){
        const x=pos[i*3],z=pos[i*3+2],f=weight(area,x,z);
        if(f<1){const h=world.kineoBase(x,z);pos[i*3+1]=h+(pos[i*3+1]-h)*f;}
      }
      const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(pos,3));g.setIndex(new T.BufferAttribute(ix,1));
      g.computeVertexNormals();g.computeBoundingSphere();
      const mesh=new T.Mesh(g,world.kineoTerrainMaterial);mesh.name='Mount Kineo adjoining measured terrain';group.add(mesh);shells.push(mesh);
    }
    const lodReply=await fetch(file('kineo-lod.bin'));if(!lodReply.ok)throw new Error('Kineo distance geometry unavailable');
    const data=await lodReply.arrayBuffer(),sizes=new DataView(data),lods=[];let start=4;
    for(let i=0;i<4;i++){const n=sizes.getUint32(start,true);start+=4;lods.push(new T.BufferAttribute(new Uint16Array(data,start,n),1));start=(start+n*2+3)&~3;}
    const records=[...origins,{file:'kineo-jointed-block.glb'},{file:'kineo-talus-pocket.glb'}];
    const models=await Promise.all(records.map(async (rec,idx)=>{
      const mesh=await readGLB(T,file(rec.file)),name=rec.file.slice(0,-4);
      mesh.name=name;mesh.userData.aerieRegional={model:name,lod:'near'};mesh.userData.nearIndex=mesh.geometry.index;mesh.userData.farIndex=lods[idx];
      if(rec.position){mesh.position.fromArray(rec.position);matchSurveyLight(T,mesh,world,rec.position);}
      else {
        // Place real-size detached scans on the two sides of the surveyed
        // nearshore rack. Find a dry foothold without shifting the measured GLBs.
        const pocket=name.includes('pocket'),z=pocket?-947.6:-931.4;
        let x=380,best=Infinity;
        for(let xx=358;xx<413;xx+=.25){
          const h=world.elevation(xx,z),slope=Math.hypot(world.elevation(xx+.5,z)-world.elevation(xx-.5,z),world.elevation(xx,z+.5)-world.elevation(xx,z-.5));
          const cost=Math.abs(h-(world.waterLevel+(pocket?2.2:.85)))+Math.max(0,slope-.36)*5;
          if(h>world.waterLevel+.24&&cost<best){best=cost;x=xx;}
        }
        const y=world.elevation(x,z);
        mesh.position.set(x,y-(pocket?.22:.053),z);mesh.rotation.y=pocket?.19:1.18;
      }
      group.add(mesh);mesh.updateMatrixWorld(true);return mesh;
    }));
    // Cache the top physical triangle under each nearshore placement. This
    // includes the actual adjoining survey and the crag's overhanging edges.
    const bins=new Map();
    for(const m of [...shells,...models]){
      m.updateMatrixWorld(true);
      const p=m.geometry.attributes.position.clone().applyMatrix4(m.matrixWorld),ix=m.geometry.index.array;
      for(let i=0;i<ix.length;i+=3){
        const u=ix[i],v=ix[i+1],w=ix[i+2],ax=p.getX(u),az=p.getZ(u),ay=p.getY(u);
        const bx=p.getX(v)-ax,bz=p.getZ(v)-az,cx=p.getX(w)-ax,cz=p.getZ(w)-az,det=bx*cz-bz*cx;
        if(Math.abs(det)<.00001)continue;
        const tri=[ax,az,ay,bx,bz,cx,cz,p.getY(v)-ay,p.getY(w)-ay,1/det];
        for(let j=Math.floor((az+Math.min(0,bz,cz))/4);j<=Math.floor((az+Math.max(0,bz,cz))/4);j++)for(let k=Math.floor((ax+Math.min(0,bx,cx))/4);k<=Math.floor((ax+Math.max(0,bx,cx))/4);k++){
          const key=k+j*32768;let group=bins.get(key);if(!group)bins.set(key,group=[]);group.push(tri);
        }
      }
    }
    world.kineoRockSurface=(x,z)=>{
      let top=-Infinity;
      for(const [ax,az,ay,bx,bz,cx,cz,by,cy,inv] of bins.get(Math.floor(x/4)+Math.floor(z/4)*32768)||[]){
        const u=((x-ax)*cz-(z-az)*cx)*inv,v=(bx*(z-az)-bz*(x-ax))*inv;
        if(u>=0&&v>=0&&u+v<=1)top=Math.max(top,ay+u*by+v*cy);
      }
      return Number.isFinite(top)?top:undefined;
    };
    let shelfGrowth=null;
    const eastWall=models.find(m=>m.name==='kineo-east-cliff');
    if(eastWall&&world.shoreThickets?.addShelf){
      const positions=eastWall.geometry.attributes.position,index=eastWall.geometry.index;
      const a=new T.Vector3(),b=new T.Vector3(),c=new T.Vector3(),normal=new T.Vector3(),center=new T.Vector3();
      const pockets=[],roots=[];
      let seed=0x244597;const random=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/4294967296);
      for(let i=0;i<index.count;i+=3){
        a.fromBufferAttribute(positions,index.getX(i));b.fromBufferAttribute(positions,index.getX(i+1));c.fromBufferAttribute(positions,index.getX(i+2));
        normal.subVectors(b,a).cross(c.sub(a)).normalize();c.fromBufferAttribute(positions,index.getX(i+2));
        if(normal.y<.76)continue;
        center.copy(a).add(b).add(c).multiplyScalar(1/3).add(eastWall.position);
        const {x,y,z}=center;
        // Distinct, sheltered diagonal shelves. Most clefts are bare, and a
        // vertical return cannot support a floating root.
        const belt1=((z+1089)/35)**2+((y-413+.16*(z+1089))/7)**2;
        const belt2=((z+1195)/44)**2+((y-366-.08*(z+1195))/6.5)**2;
        const belt3=((z+1165)/31)**2+((y-436-.12*(z+1165))/5.1)**2;
        const inside=Math.min(belt1,belt2,belt3);
        if(inside>=1)continue;
        const rank=random()*(1-.60*inside);
        pockets.push({x,y,z,slopeX:-normal.x/normal.y,slopeZ:-normal.z/normal.y,rank});
      }
      pockets.sort((a,b)=>b.rank-a.rank);
      for(const p of pockets){
        if(roots.length>=58)break;
        if(roots.some(r=>Math.hypot(p.x-r.x,p.z-r.z)<2.05&&Math.abs(p.y-r.y)<2.8))continue;
        const h=(1.0+2.95*p.rank)*(.76+.47*random()),cell=[0,2,8,9,12,14][Math.floor(random()*6)];
        roots.push({...p,h,cell,a:random()*Math.PI*2,shade:.95+.16*random()});
      }
      shelfGrowth=world.shoreThickets.addShelf(roots);
    }
    const names=models.map(m=>m.name);
    const levels=models.map(m=>{
      const span=m.name.includes('east-cliff')?1180:m.name.includes('margin')?145:m.name.includes('pocket')?70:32;
      const lower=span*.74,upper=span*1.36;
      const lowGeometry=new T.BufferGeometry();
      for(const [key,attr] of Object.entries(m.geometry.attributes))lowGeometry.setAttribute(key,attr);
      lowGeometry.setIndex(m.userData.farIndex);lowGeometry.boundingSphere=m.geometry.boundingSphere;
      const lowMaterial=m.material.clone();
      if(m.material.isShaderMaterial)lowMaterial.uniforms=m.material.uniforms;
      const low=new T.Mesh(lowGeometry,lowMaterial);
      low.position.copy(m.position);low.quaternion.copy(m.quaternion);low.name=m.name+' distant';
      low.userData.aerieRegional={model:m.name,lod:'far'};group.add(low);
      for(const [lod,mat] of [m.material,lowMaterial].entries()){
        mat.customProgramCacheKey=()=>'kineo-survey-'+m.name+'-'+lod;
        mat.onBeforeCompile=shader=>{
          shader.uniforms.kineoOrigin={value:m.position};
          shader.fragmentShader='uniform vec3 kineoOrigin;\n'+shader.fragmentShader.replace(/void\s+main\s*\(\s*\)\s*\{/, `void main(){
            float threshold=1.-smoothstep(${lower.toFixed(2)},${upper.toFixed(2)},distance(cameraPosition,kineoOrigin));
            float mask=fract(52.9829189*fract(dot(floor(gl_FragCoord.xy),vec2(.06711056,.00583715))));
            ${lod?'if(mask<threshold)discard;':'if(mask>=threshold)discard;'}`);
        };
      }
      return {m,low,lower,upper};
    });
    const removeLookout=addSummitLookout(T,group,world);
    return {names,update(p){
      for(const {m,low,lower,upper} of levels){
        const d=Math.hypot(p.x-m.position.x,p.y-m.position.y,p.z-m.position.z);
        // The coarse cliff and wave-washed rack remain physically present to the horizon.
        // Real camera distance interpolates the two index sets inside this padded band.
        m.visible=d<upper+42;low.visible=d>lower-42;
      }
    },dispose(){
      removeLookout();
      if(shelfGrowth){shelfGrowth.removeFromParent();shelfGrowth.geometry.dispose();}
      for(const {low} of levels){low.geometry.dispose();low.material.dispose();}
      for(const m of models){m.geometry.dispose();const mat=m.userData.originalSurveyMaterial||m.material;if(mat!==m.material)m.material.dispose();for(const tx of new Set([mat.map,mat.normalMap,mat.roughnessMap]))tx.dispose();mat.dispose();}
      for(const m of shells)m.geometry.dispose();
    }};
  };
})();
